import assert from 'node:assert/strict';
import fs from 'node:fs';
import test from 'node:test';
import vm from 'node:vm';
// The paid internal service was explicitly retired; verify its replacement and external safety.
for(const base of ['', 'native/private-small-phone/XcodeProject/PhoneCompanionTest/PhoneWeb.bundle/']){
 const app=fs.readFileSync(base+'app.js','utf8'),album=fs.readFileSync(base+'photo-album.js','utf8');
 const extract=name=>{const match=app.match(new RegExp('function '+name+'\\([^\\n]+'));assert(match,name);return match[0]};
 test(base+'saved internal flags cannot activate voice, ASR, or the retired backend',()=>{
  const settings={tts:{relay:true,enabled:true},stt:{relay:true},aiCore:{enabled:true,url:'https://retired.example'}};
  const c=vm.createContext({S:{settings},fetch(){throw Error('unexpected network')}});
  for(const name of ['aiCoreOn','aiCoreUrl','ttsRelayOn','sttRelayOn'])vm.runInContext(extract(name),c);
  assert.equal(c.aiCoreOn(),false);assert.equal(c.aiCoreUrl(),'');assert.equal(c.ttsRelayOn(settings.tts),false);assert.equal(c.sttRelayOn(),false);
  assert.equal(settings.tts.relay,true,'do not erase user archives');
  assert.doesNotMatch(app,/await aiRelay\(|await licenseSyncAiIdentity\(/);
 });
 test(base+'album renders the active user avatar, real item count, and only approved categories',()=>{
  const c=vm.createContext({S:{me:{name:'North',avatar:'my-avatar'},photoAlbum:{items:[{name:'Photo',src:'image.jpg'}]}},esc:s=>String(s).replaceAll('<','&lt;'),av:a=>'<img src="'+a+'">',storedImageElementSource:s=>s,render(){},toast(){}});
  vm.runInContext(album,c);let html=c.renderPhotoAlbum();assert.match(html,/my-avatar/);assert.match(html,/人物与宠物/);assert.doesNotMatch(html,/AI账户|媒体类型|1899/);
  c.photoAlbumTab('library');html=c.renderPhotoAlbum();assert.match(html,/1 个项目/);assert.match(html,/image.jpg/);
  c.S.photoAlbum.items=[];assert.match(c.renderPhotoAlbum(),/0 个项目/);assert.match(c.renderPhotoAlbum(),/还没有照片/);
 });
 test(base+'replacement module has no account requests and the old module is absent',()=>{
  assert.equal(fs.existsSync(base+'ai-account.js'),false);assert.doesNotMatch(album,/aiRelay\(|localStorage\.|pickFile\(/);
  const html=fs.readFileSync(base+'小手机.html','utf8');assert.match(html,/photo-album\.js/);assert.doesNotMatch(html,/ai-account\.js/);
 });
}

