 test(base+'one comment call optionally likes the photo using its existing vision cache',async()=>{const {c,S,row,role}=fixture();S.settings={chat:{base:'external',key:'fixture'}};let requests=0;c.photoAlbumEnsureVision=async()=>true;c.chatAPI=async()=>{requests++;return '这只小猫真可爱。[喜欢照片]'};await c.photoAlbumGenerateComment(row,role);assert.equal(requests,1);assert.equal(row.roleComment.text,'这只小猫真可爱。');assert.equal(row.roleLikes.r.name,'林予');assert.equal(row.desc,'小猫');});
