for(const base of ['', 'native/private-small-phone/XcodeProject/PhoneCompanionTest/PhoneWeb.bundle/'])test(base+'viewer trash deletes only the current photo, rolls back failed saves and returns after the last photo',async()=>{const a={id:'a',src:'album:__album_photo_a',category:'回忆',likedByMe:true},b={id:'b',src:'b.jpg',category:'回忆'},other={id:'other',src:'other.jpg',accountId:'other'};let good=false,release;const deleted=[],c=vm.createContext({S:{me:{active:'main'},photoAlbum:{items:[a,b,other]}},esc:String,storedImageElementSource:s=>s,render(){},toast(){},document:{querySelector:()=>null},saveNowAsync:async()=>good,imgDel:async k=>deleted.push(k)});vm.runInContext(fs.readFileSync(base+'photo-album.js','utf8'),c);c.photoAlbumOpen(0,'回忆');assert.match(c.renderPhotoAlbum(),/onclick="photoAlbumDeleteCurrent\(\)"/);await c.photoAlbumDeleteCurrent();assert.equal(c.S.photoAlbum.items.length,3);assert.equal(deleted.length,0);assert.equal(vm.runInContext('_photoAlbumViewer.rows[_photoAlbumViewer.index].id',c),'a');good=true;c.saveNowAsync=()=>new Promise(r=>release=r);const pending=c.photoAlbumDeleteCurrent();await c.photoAlbumDeleteCurrent();release(true);await pending;assert.deepEqual(Array.from(c.S.photoAlbum.items,r=>r.id),['b','other']);assert.deepEqual(deleted,[]);assert.equal(c.S.photoAlbum.deletedItems[0].row,a);assert.equal(vm.runInContext('_photoAlbumViewer.rows[_photoAlbumViewer.index].id',c),'b');assert.equal(c.photoAlbumGroupRows('我的喜欢').length,0);c.saveNowAsync=async()=>true;c.S.me.active='other';await c.photoAlbumDeleteCurrent();assert.equal(c.S.photoAlbum.items.length,2);c.S.me.active='main';await c.photoAlbumDeleteCurrent();assert.deepEqual(Array.from(c.S.photoAlbum.items,r=>r.id),['other']);assert.equal(vm.runInContext('_photoAlbumViewer',c),null);assert.match(c.renderPhotoAlbum(),/data-photo-album="library"/);});

for(const base of ['', 'native/private-small-phone/XcodeProject/PhoneCompanionTest/PhoneWeb.bundle/'])test(base+'deleted photo notice snapshots known facts before removal, merges batches and respects permission and storage gates',async()=>{const role={id:'lover'},known={id:'cat',accountId:'main',src:'cat.jpg',title:'猫咪',category:'人物与宠物',takenAt:'2026-10-05T11:00',location:'北京',desc:'一只眯眼的小猫',visionState:'success'},unknown={id:'sea',src:'sea.jpg',title:'海边',category:'旅程',desc:'不能使用的失败识别内容',visionState:'failed'},hidden={id:'hidden',src:'hidden.jpg',coupleRoleId:'old-lover',title:'旧情侣私密标题',desc:'旧情侣私密画面',visionState:'success'},other={id:'alt',src:'alt.jpg',accountId:'other',title:'其他账号私密标题'},notes=[];const S={me:{active:'main'},couple:{cid:'lover',albumAuth:true,albumAuthCid:'lover'},photoAlbum:{items:[known,unknown,hidden,other]}};let good=false,release;const c=vm.createContext({S,esc:String,storedImageElementSource:s=>s,getC:id=>id==='lover'?role:null,uid:()=>String(notes.length),featureEventNote:(k,n)=>n,scheduleFeatureReply:(id,n)=>notes.push(n),render(){},toast(){},document:{querySelector:()=>null},saveNowAsync:async()=>good,imgDel:async()=>{},runVisionForMessage(){throw Error('deletion must not recognize images')}});vm.runInContext(fs.readFileSync(base+'photo-album.js','utf8'),c);const state={owner:'main',rows:new Set([known,unknown,hidden,other])};await c.photoAlbumDeleteSelected(state);assert.equal(notes.length,0);assert.equal(S.photoAlbum.items.length,4);good=true;c.saveNowAsync=()=>new Promise(r=>release=r);const pending=c.photoAlbumDeleteSelected(state);known.desc='删除过程中变动的描述';release(true);await pending;assert.equal(notes.length,1);assert.match(notes[0],/删除了 3 张/);assert.match(notes[0],/猫咪/);assert.match(notes[0],/一只眯眼的小猫/);assert.match(notes[0],/人物与宠物/);assert.match(notes[0],/2026-10-05T11:00/);assert.match(notes[0],/北京/);assert.match(notes[0],/海边/);assert.doesNotMatch(notes[0],/不能使用的失败识别内容|旧情侣私密|其他账号私密|删除过程中变动|cat.jpg|sea.jpg/);assert.equal(S.photoAlbum.items.length,1);assert.equal(c.photoAlbumRoleRows(role).length,0);const last={id:'last',src:'last.jpg',title:'不应通知'};S.photoAlbum.items.push(last);const revoked=c.photoAlbumDeleteSelected({owner:'main',rows:new Set([last])});S.couple.albumAuth=false;release(true);await revoked;assert.equal(notes.length,1);});

